#!/usr/bin/env python3
"""Apply script: Smart Care (Cigna) TOB extraction fix + Print/PDF export.
Run from the HealthCross repo root: python3 apply_smart_care_tob_fix.py
Each file is self-checksummed (SHA256) so a silent partial-write is caught
immediately rather than discovered later - see MARKER below.
"""
import base64, hashlib, os, sys

MARKER = "SMART_CARE_TOB_FIX_2026_08_04"

FILES = [
    {
        'path': 'app/ingestion/international_tob.py',
        'sha256': '147398ee412b71c3be7fbbe6e5f9fc27fdaa81a1bd37a65dc83d81fb99d71bae',
        'size': 27467,
        'b64': '',
    },
    {
        'path': 'app/ingestion/labeled_row_benefits_pdf.py',
        'sha256': '2ba0af831ecb181c78248fab07f8d9d444a488fbe8f0c6186fb630bf955f7e2e',
        'size': 12806,
        'b64': '',
    },
    {
        'path': 'app/reference/benefit_category_mapping.py',
        'sha256': '9f75243998ab1ef1f728438a1419c6e79fd90084e0889827d6331828b4b9b4ca',
        'size': 36768,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': 'c0c26dd9a633f956e74df8eb1f619f50d3c260f58a63be5ae89c51d886848222',
        'size': 135002,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
